begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(28);
insert into auth.users(id,email) values('f1111111-1111-4111-8111-111111111111','recovery-student@example.com'),('f2222222-2222-4222-8222-222222222222','recovery-other@example.com');
update public.profiles set role='student' where id='f1111111-1111-4111-8111-111111111111';
create temp table orders(name text, payload jsonb);
insert into orders values('a',public.create_topup_payment_order('f1111111-1111-4111-8111-111111111111',10000,'recovery-order-a'));
select is((select payload->>'status' from orders where name='a'),'pending','fresh order returns canonical pending state');
select is((public.claim_topup_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='a'),'recovery-payment-a',10000)->>'reconciliationRequired'),'false','first claim may approve once');
select is((public.claim_topup_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='a'),'recovery-payment-a',10000)->>'reconciliationRequired'),'true','repeat claim must query provider first');
select is((public.create_topup_payment_order('f1111111-1111-4111-8111-111111111111',10000,'recovery-order-a')->>'status'),'confirming','same key returns actual processing state');
select throws_ok($$select public.create_topup_payment_order('f1111111-1111-4111-8111-111111111111',30000,'recovery-order-a')$$,'P0001','idempotency key mismatch','amount cannot change under same key');
select public.fail_topup_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='a'),'ALREADY_PROCESSED_PAYMENT');
select is((public.claim_topup_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='a'),'recovery-payment-a',10000)->>'reconciliationOnly'),'true','legacy failed bound payment can only reconcile');
select is((public.create_topup_payment_order('f1111111-1111-4111-8111-111111111111',10000,'recovery-order-a')->>'status'),'needs_review','legacy failure must not unlock another order as terminal');
select throws_ok($$select public.claim_topup_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='a'),'foreign-payment',10000)$$,'P0001','payment key mismatch','recovery keeps bound payment identity');
select is((public.confirm_toss_topup_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='a'),'recovery-payment-a','{"status":"DONE"}')->>'status'),'confirmed','verified provider approval may be posted after response loss');
select public.confirm_toss_topup_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='a'),'recovery-payment-a','{"status":"DONE"}');
select is((select count(*) from public.wallet_transactions where kind='topup_confirmed' and to_user_id='f1111111-1111-4111-8111-111111111111'),1::bigint,'repeated DB confirmation posts once');
select is((public.get_wallet_balances('f1111111-1111-4111-8111-111111111111')->>'topupAvailable')::bigint,10000::bigint,'verified topup affects balance exactly once');
select public.fail_topup_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='a'),'LATE_FAILURE');
select is((select metadata->>'failureCode' from public.wallet_transactions where provider_order_id=(select payload->>'orderId' from orders where name='a')),'ALREADY_PROCESSED_PAYMENT','late failure cannot alter an already posted order');
select is((public.create_topup_payment_order('f1111111-1111-4111-8111-111111111111',10000,'recovery-order-a')->>'status'),'confirmed','order lookup prefers the posted settlement');
insert into orders values('b',public.create_topup_payment_order('f1111111-1111-4111-8111-111111111111',30000,'recovery-order-b'));
insert into orders values('c',public.create_topup_payment_order('f1111111-1111-4111-8111-111111111111',50000,'recovery-order-c'));
select public.claim_topup_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='c'),'recovery-payment-c',50000);
grant select on orders to authenticated;
set local request.jwt.claim.sub='f1111111-1111-4111-8111-111111111111';
set local role authenticated;
select is((public.cancel_pending_topup_order((select payload->>'orderId' from orders where name='b'))->>'status'),'cancelled','owner may cancel only an unclaimed pending order');
select is((public.cancel_pending_topup_order((select payload->>'orderId' from orders where name='b'))->>'status'),'cancelled','pending cancellation is idempotent');
select throws_ok($$select public.cancel_pending_topup_order((select payload->>'orderId' from orders where name='c'))$$,'P0001','topup order requires reconciliation','claimed order cannot be cancelled by the browser');
select ok(not has_function_privilege('authenticated','public.claim_topup_payment(uuid,text,text,bigint)','EXECUTE'),'client cannot claim a financial approval');
reset role;
select is((public.create_topup_payment_order('f1111111-1111-4111-8111-111111111111',30000,'recovery-order-b')->>'status'),'failed','cancelled same key is a terminal order');
select throws_ok($$select public.claim_topup_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='b'),'recovery-new-key',30000)$$,'P0001','topup order failed','cancelled unbound order cannot be approved');
select isnt(public.create_topup_payment_order('f1111111-1111-4111-8111-111111111111',30000,'recovery-order-new')->>'orderId',(select payload->>'orderId' from orders where name='b'),'new key creates distinct order after known cancellation');
set local request.jwt.claim.sub='f2222222-2222-4222-8222-222222222222';
set local role authenticated;
select throws_ok($$select public.cancel_pending_topup_order((select payload->>'orderId' from orders where name='c'))$$,'P0001','topup order not found','other account cannot cancel an order');
reset role;
select ok(not has_function_privilege('anon','public.cancel_pending_topup_order(text)','EXECUTE'),'anonymous cancellation denied');
set local request.jwt.claim.sub='f1111111-1111-4111-8111-111111111111';
insert into orders values('m',public.create_membership_payment_order('f1111111-1111-4111-8111-111111111111','recovery-membership-a'));
select is((public.claim_membership_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='m'),'recovery-membership-key',9900)->>'reconciliationRequired'),'false','fresh membership claim may approve');
select is((public.claim_membership_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='m'),'recovery-membership-key',9900)->>'reconciliationRequired'),'true','repeat membership claim requires provider query');
select public.confirm_toss_membership_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='m'),'recovery-membership-key','{"status":"DONE"}');
select is((public.claim_membership_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='m'),'recovery-membership-key',9900)->>'status'),'confirmed','posted membership is reused');
select throws_ok($$select public.claim_membership_payment('f1111111-1111-4111-8111-111111111111',(select payload->>'orderId' from orders where name='m'),'other-membership-key',9900)$$,'P0001','payment key mismatch','confirmed membership still validates payment key');
select throws_ok($$select public.claim_membership_payment('f2222222-2222-4222-8222-222222222222',(select payload->>'orderId' from orders where name='m'),'recovery-membership-key',9900)$$,'P0001','payment order ownership mismatch','membership recovery validates ownership');
select is((public.get_wallet_balances('f1111111-1111-4111-8111-111111111111')->>'topupAvailable')::bigint,10000::bigint,'pending cancellation and membership do not mint wallet points');
select * from finish();
rollback;
